"""Gera o mapa consultável a partir de docs/jornada/estado.json. Sem rede."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'docs/jornada/estado.json').read_text())
h=lambda s:html.escape(str(s),quote=True)
repo='https://github.com/rfmss/escrevaral/blob/main/'
link=lambda p:f'<a href="{repo+h(p)}">{h(p.split("/")[-1])}</a>'
phases=[]
for p in d['phases']:
    evidence=' · '.join(link(x) for x in p['evidence']) or 'Evidências serão vinculadas quando esta entrega existir.'
    phases.append(f'''<details class="phase" id="{p['id']}" data-search="{h((p['id']+' '+p['title']+' '+p['status']+' '+p['goal']).lower())}"><summary><span class="number">{p['id'][1:]}</span><span class="phase-title">{h(p['title'])}<small>{h(p['goal'])}</small></span><span class="badge">{h(p['status'])}</span><span class="plus" aria-hidden="true">+</span></summary><div class="phase-body"><p class="dependency">Depende de: {h(', '.join(p['depends']) or 'base já existente')}. Etapas com dependências distintas podem avançar em paralelo.</p><ul>{''.join('<li>'+h(t)+'</li>' for t in p['tasks'])}</ul><h4>Como saber que esta entrega está pronta</h4><p>{h(p['done'])}</p><p class="evidence">{evidence}</p></div></details>''')
areas=''.join(f'<details class="area"><summary>{h(a["title"])}</summary><p>{h(a["scope"])}</p></details>' for a in d['areas'])
cards=[]
for e in d['examples']:
    assert d['sample'][e['start']:e['end']]==e['text']
    source='Leitura proposta para o exemplo do autor; revisão linguística independente pendente.' if e['source']=='EXEMPLO-AUTOR' else 'Referência de apoio: '+e['source']+'. Aplicação ao exemplo: leitura demonstrativa, não validação de um motor.'
    parent='Recorte contido em '+e['parent']+'.' if e['parent'] else 'Relação descrita abaixo.'
    cards.append(f'''<article class="finding"><div class="finding-head"><span class="label">{e['id']} · anotação manual</span><span class="quiet">{h(parent)}</span></div><h4>{h(e['title'])}</h4><blockquote>{h(e['text'])}</blockquote><p>{h(e['simple'])}</p><button type="button" class="locate" data-start="{e['start']}" data-end="{e['end']}">Localizar no original <span aria-hidden="true">↗</span></button><details><summary>Entender a leitura e seus limites</summary><p>{h(e['reading'])}</p><p>{h(e['limit'])}</p><p class="quiet">{h(source)}</p></details></article>''')
books=''.join(f'<details class="area"><summary>{h(b["id"])} · {h(b["title"])}</summary><p><strong>{h(b["author"])}</strong><br>{h(b["edition"])}</p><p>{h(b["role"])}</p><p><strong>Estado:</strong> {h(b["status"])}</p><p><strong>Qualidade do arquivo:</strong> {h(b["quality"])}</p><p><strong>Próxima leitura:</strong> {h(b["next"])}</p></details>' for b in d.get('books',[]))
sources=''.join(f'<li id="{s["id"]}"><a href="{h(s["url"])}">{s["id"]} · {h(s["title"])}</a></li>' for s in d['sources'])
css='''
:root{--paper:#f3f1e8;--ink:#23372e;--muted:#57655d;--line:#b9c0ae;--leaf:#e2e8d8;--white:#fcfbf6;--accent:#865333}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:95px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--accent)}button,input,textarea{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:4px}button{border:1px solid var(--ink);padding:9px 14px;background:transparent;color:var(--ink);border-radius:3px}button:hover{background:var(--leaf)}[hidden]{display:none!important}h1,h2,h3,h4,p{margin-top:0}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.12}h1{font-size:clamp(40px,6vw,76px);letter-spacing:-.04em;max-width:860px;margin:22px 0}h2{font-size:clamp(31px,4vw,46px);letter-spacing:-.025em;margin-bottom:16px}h3{font-size:21px}h4{font-size:17px}header{border-bottom:1px solid var(--line);padding:18px 0}header .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-weight:800;text-decoration:none;letter-spacing:-.04em;font-size:23px}.brand span{border:1px solid var(--ink);padding:0 3px;margin-left:2px}.wrap{width:min(1180px,calc(100% - 64px));margin:auto}.label,.eyebrow{font:12px/1.4 ui-monospace,monospace;text-transform:uppercase;letter-spacing:.09em}.eyebrow{display:inline-flex;gap:12px;align-items:center}.eyebrow:before{content:"";width:26px;height:1px;background:var(--ink)}.hero{padding:64px 0 38px}.lead{font-size:20px;max-width:760px;color:var(--muted)}.hero-note{max-width:820px;border-left:3px solid var(--accent);padding-left:18px}.stamp{display:inline-block;border:1px solid var(--line);padding:6px 10px;font-size:12px}.overview{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin:34px 0}.overview article{background:var(--white);border:1px solid var(--line);padding:24px;position:relative}.overview article:before{content:"";position:absolute;left:8px;top:8px;width:7px;height:7px;border-left:1px solid var(--line);border-top:1px solid var(--line)}.overview h3{margin:9px 0}.overview p{margin-bottom:0;color:var(--muted);font-size:14px}nav{position:sticky;top:0;z-index:5;background:var(--paper);border-block:1px solid var(--line)}nav .wrap{display:flex;gap:26px;overflow:auto}nav a{padding:14px 0;text-decoration:none;white-space:nowrap;font-size:14px;font-weight:650}section.chapter{padding:64px 0;border-bottom:1px solid var(--line)}.section-head{display:flex;gap:32px;justify-content:space-between;align-items:start;margin-bottom:26px}.section-head p{max-width:480px;color:var(--muted)}.search{display:block;margin-bottom:20px;font-size:14px}.search input{display:block;width:100%;margin-top:8px;border:1px solid var(--line);padding:12px;background:var(--white);color:var(--ink)}.phase{border:1px solid var(--line);background:var(--white);margin-bottom:10px}.phase>summary{list-style:none;display:flex;align-items:center;gap:20px;padding:21px;cursor:pointer}.phase>summary::-webkit-details-marker{display:none}.number{font:22px Georgia,serif;color:var(--muted);min-width:32px}.phase-title{flex:1;font-weight:650;font-size:18px}.phase-title small{display:block;font-size:13px;font-weight:400;color:var(--muted);margin-top:4px}.badge{border:1px solid var(--line);font-size:11px;border-radius:2px;padding:4px 8px;max-width:170px;text-align:center}.plus{font-size:24px;line-height:1}.phase[open] .plus{transform:rotate(45deg)}.phase-body{padding:0 24px 22px 74px;max-width:990px}.dependency,.evidence,.quiet{font-size:13px;color:var(--muted)}.phase-body h4{margin:22px 0 6px}.phase-body .evidence{overflow-wrap:anywhere}.next{background:var(--leaf);border:1px solid var(--line);padding:26px;margin-top:26px}.next ol{margin-bottom:0;padding-left:24px}.areas{display:grid;grid-template-columns:1fr 1fr;gap:12px}.area{border-top:1px solid var(--line);padding:17px 0}.area summary{cursor:pointer;font-weight:650}.area p{font-size:14px;color:var(--muted);margin:14px 0 0}.demo{border:1px solid var(--ink);background:var(--white);padding:26px;margin-top:28px}.demo-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:24px}.switch{display:inline-flex;gap:12px;align-items:center;flex-shrink:0}.switch i{display:block;width:32px;height:18px;border-radius:20px;background:#bdc4b5;position:relative}.switch i:after{content:"";position:absolute;left:3px;top:3px;width:12px;height:12px;border-radius:50%;background:var(--white)}.switch[aria-checked=true]{background:var(--ink);color:white}.switch[aria-checked=true] i:after{left:17px}.demo-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:28px}.demo-layout.open{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.manuscript label{display:block;font-size:13px;color:var(--muted);margin-bottom:12px}.manuscript textarea{display:block;width:100%;height:465px;resize:vertical;border:1px solid var(--line);background:#f8f6ee;padding:24px;font:19px/1.8 Georgia,serif;color:var(--ink)}.integrity{border-top:1px solid var(--line);padding-top:12px;margin:14px 0 0;font-size:13px}.curtain{min-width:0;border-left:1px solid var(--line);padding-left:25px}.curtain h3{font:29px Georgia,serif;margin-bottom:10px}.lens-choice{background:var(--leaf);font-weight:600;margin:8px 0 20px}.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);padding-bottom:10px}.tabs button{font-size:13px;padding:7px 10px}.tabs button[aria-selected=true]{background:var(--ink);color:white}.result-panel{max-height:640px;overflow:auto;padding-right:10px;padding-top:18px}.finding{padding:20px 0;border-bottom:1px solid var(--line)}.finding:first-child{padding-top:0}.finding-head{display:flex;flex-wrap:wrap;gap:5px;justify-content:space-between}.finding h4{margin:12px 0}.finding blockquote{border-left:2px solid var(--accent);padding-left:14px;margin:16px 0;font:18px/1.5 Georgia,serif;overflow-wrap:anywhere}.finding p{font-size:14px}.finding details{margin-top:14px}.finding summary{font-size:13px;cursor:pointer}.finding details p{margin:12px 0}.locate{font-size:13px;padding:6px 10px}.reading-note{padding:16px;border:1px dashed var(--line);font-size:14px}.guides{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.guide{padding:24px;border:1px solid var(--line);background:var(--white)}.guide p{font-size:14px;color:var(--muted)}.guide a{font-weight:600;font-size:14px}.contract{display:grid;grid-template-columns:1fr 1fr;gap:20px}.contract div{padding:20px 0;border-top:1px solid var(--line)}.contract strong{display:block;margin-bottom:8px}.contract p{font-size:14px;color:var(--muted);margin:0}footer{padding:35px 0;color:var(--muted);font-size:13px}.source-list{font-size:13px;padding-left:18px}.source-list li{margin:8px 0}.source-list a{overflow-wrap:anywhere}@media(max-width:800px){.wrap{width:calc(100% - 32px)}.hero{padding-top:38px}.overview,.guides{grid-template-columns:1fr}.overview{gap:10px}.overview article{padding:20px}.section-head{display:block}.section-head p{max-width:none}.areas,.contract{grid-template-columns:1fr}.phase>summary{flex-wrap:wrap;gap:10px;padding:16px}.phase-title{min-width:calc(100% - 55px)}.badge{margin-left:42px}.plus{margin-left:auto}.phase-body{padding:0 16px 18px}.demo{padding:16px}.demo-bar{align-items:flex-start;flex-direction:column}.demo-layout.open{grid-template-columns:1fr}.curtain{padding:22px 0 0;border-left:0;border-top:1px solid var(--line)}.manuscript textarea{height:380px;padding:16px}.result-panel{max-height:none;padding-right:0}header .quiet{font-size:11px}nav .wrap{gap:20px}section.chapter{padding:42px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{nav,.search,button{display:none!important}.wrap{width:100%}.hero,section.chapter{padding:20px 0}.phase,.guide,.finding{break-inside:avoid}body{background:white}}
'''
js='''(function(){'use strict';var toggle=document.getElementById('switch'),curtain=document.getElementById('curtain'),layout=document.getElementById('demo-layout'),sample=document.getElementById('sample'),original=sample.value,results=document.getElementById('demo-results'),notice=document.getElementById('demo-status');toggle.addEventListener('click',function(){var on=toggle.getAttribute('aria-checked')!=='true';toggle.setAttribute('aria-checked',String(on));document.getElementById('switch-state').textContent=on?'Ligado':'Desligado';curtain.hidden=!on;layout.className='demo-layout'+(on?' open':'');if(!on){results.hidden=true;notice.textContent='Cortina fechada. O texto continua intacto.';}else{notice.textContent='Escolha a análise. Este exemplo usa anotações manuais.';}});document.getElementById('lens-sub').addEventListener('click',function(){results.hidden=false;notice.textContent='Cinco recortes anotados manualmente. Não é uma análise automática nem exaustiva.';document.getElementById('tab-trechos').click();});var buttons=document.querySelectorAll('[role=tab]');function selectTab(button){for(var i=0;i<buttons.length;i++){var active=buttons[i]===button;buttons[i].setAttribute('aria-selected',String(active));buttons[i].tabIndex=active?0:-1;document.getElementById(buttons[i].getAttribute('aria-controls')).hidden=!active;}}for(var i=0;i<buttons.length;i++){buttons[i].addEventListener('click',function(){selectTab(this);});buttons[i].addEventListener('keydown',function(e){if(e.keyCode===37||e.keyCode===39){e.preventDefault();var target=this===buttons[0]?buttons[1]:buttons[0];selectTab(target);target.focus();}});}var locators=document.querySelectorAll('.locate');for(var j=0;j<locators.length;j++)locators[j].addEventListener('click',function(){sample.focus();sample.setSelectionRange(Number(this.getAttribute('data-start')),Number(this.getAttribute('data-end')));notice.textContent='Trecho selecionado no original. Nenhuma palavra foi alterada.';document.getElementById('integrity').textContent=sample.value===original?'Original preservado · nenhuma alteração':'O exemplo mudou; recarregue a demonstração.';});document.getElementById('filter').addEventListener('input',function(){var q=this.value.toLowerCase(),nodes=document.querySelectorAll('.phase'),n=0;for(var i=0;i<nodes.length;i++){var match=nodes[i].getAttribute('data-search').indexOf(q)!==-1;nodes[i].hidden=!match;if(match)n++;}document.getElementById('filter-status').textContent=n+' etapas exibidas.';});}());'''
page=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="description" content="Mapa permanente de estudo, construção e validação linguística do Escrevaral. Etapas, limites e demonstração da experiência proposta."><title>Jornada linguística — Escrevaral</title><style>{css}</style></head><body>
<header><div class="wrap"><a class="brand" href="../">ESCREVA<span>RAL</span></a><span class="quiet">Caderno de construção · {h(d['updated'])}</span></div></header>
<main><div class="wrap hero"><div class="eyebrow">Mapa permanente · jornada linguística</div><h1>Do estudo dos livros<br>à leitura do seu texto.</h1><p class="lead">{h(d['purpose'])}</p><p class="hero-note">Este é o lugar para saber o que existe, o que falta e como continuar. O conhecimento dos livros deve se transformar em regras, testes e explicações que você possa conferir.</p><div class="overview"><article><span class="label">Já no produto</span><h3>Uma base em funcionamento</h3><p>Expressões e repetição estabilizadas, triagem limitada e escolhas preservadas. Classes no contexto ainda têm cobertura parcial.</p></article><article><span class="label">Próximo passo</span><h3>Livros → conhecimento verificável</h3><p>Oito arquivos catalogados; leitura inicial parcial registrada. Cada obra tem papel, edição, intervalos consultados e pendências. Nenhuma leitura integral foi declarada.</p></article><article><span class="label">A experiência desejada</span><h3>Uma cortina de análise</h3><p>Ligar Escrevaral, escolher uma única lente e ler os trechos explicados na mesma área, um exame por vez. O manuscrito permanece intacto.</p></article></div><span class="stamp">A cortina e o detector geral de subordinadas ainda são propostas.</span></div>
<nav aria-label="Seções da jornada"><div class="wrap"><a href="#roteiro">O roteiro</a><a href="#conhecimento">O que estudar</a><a href="#biblioteca">Os livros</a><a href="#experiencia">Experimente a ideia</a><a href="#continuidade">Como continuar</a></div></nav>
<div class="wrap"><section class="chapter" id="roteiro"><div class="section-head"><div><span class="eyebrow">01 · da base à manutenção</span><h2>Um caminho com evidências.</h2></div><p>Abra cada etapa para ver a entrega e seu critério de conclusão. Não há porcentagem inventada de “língua aprendida”. Etapas podem avançar em paralelo conforme suas dependências.</p></div><label class="search" for="filter">Encontrar uma etapa<input type="search" id="filter" placeholder="Ex.: livros, subordinadas, cortina…"></label><p id="filter-status" class="quiet" aria-live="polite">12 etapas exibidas.</p>{''.join(phases)}<div class="next"><span class="label">A fila de agora</span><ol>{''.join('<li>'+h(x)+'</li>' for x in d['next'])}</ol></div></section>
<section class="chapter" id="conhecimento"><div class="section-head"><div><span class="eyebrow">02 · mapa de cobertura</span><h2>O que precisamos compreender.</h2></div><p>Este índice define o escopo de estudo. Um tópico listado não significa uma função pronta. O aprofundamento depende das obras e da avaliação de cada módulo.</p></div><div class="areas">{areas}</div><p class="reading-note">Dicionário, análise contextual e explicação são camadas diferentes. Saber que uma palavra pode ser verbo ou substantivo não decide sua função numa passagem. Abordagens gramaticais divergentes devem ser identificadas.</p></section>
<section class="chapter" id="biblioteca"><div class="section-head"><div><span class="eyebrow">Acervo inicial · estudo em andamento</span><h2>Um guia principal. Apoios por demanda.</h2></div><p>Catalogados e inspecionados em trechos selecionados. As obras completas não são distribuídas aqui. Estilo editorial, variação, literatura e processo criativo exigem leituras com escopos próprios.</p></div><div class="areas">{books}</div><p class="reading-note">O Novo manual da redação tem OCR ruidoso e completude pendente. Edições antigas preservam escolhas de sua época; precisamos verificar cada critério antes de aplicá-lo hoje. Ensaios sobre inglês não são uma gramática do português.</p><p>{link('docs/jornada/LEITURA-INICIAL.md')} · {link('docs/jornada/fontes.json')} · {link('docs/jornada/corpus-inicial.json')}</p></section>
<section class="chapter" id="experiencia"><div class="section-head"><div><span class="eyebrow">03 · seu exemplo, nossa referência</span><h2>O texto fica. A análise se abre.</h2></div><p>Uma demonstração manual da experiência proposta. Ligue Escrevaral e escolha Orações subordinadas. Os recortes foram preparados para este parágrafo; não há detector geral funcionando aqui.</p></div><div class="demo"><div class="demo-bar"><div><span class="label">Demonstração · texto do autor</span><p class="quiet" style="margin:6px 0 0">Não acessa seus cadernos nem grava o manuscrito.</p></div><button id="switch" class="switch" type="button" role="switch" aria-checked="false" aria-controls="curtain" aria-label="Escrevaral"><i aria-hidden="true"></i>Escrevaral <strong id="switch-state">Desligado</strong></button></div><div id="demo-layout" class="demo-layout"><div class="manuscript"><label for="sample">Original · leitura e seleção, sem edição nesta demonstração</label><textarea id="sample" readonly spellcheck="false">{h(d['sample'])}</textarea><p id="integrity" class="integrity">Original preservado · nenhuma alteração</p></div><aside id="curtain" class="curtain" hidden aria-label="Cortina Escrevaral"><h3>O que você quer observar?</h3><p class="quiet">Uma lente por vez, sempre por sua escolha. Ligar não inicia análise geral. Na versão futura, trocar de lente cancela a anterior.</p><button id="lens-sub" class="lens-choice" type="button">Orações subordinadas</button><div id="demo-results" hidden><div class="tabs" role="tablist" aria-label="Leitura do exemplo"><button id="tab-trechos" role="tab" aria-selected="true" aria-controls="panel-trechos" type="button">Trechos e leitura</button><button id="tab-limites" role="tab" aria-selected="false" aria-controls="panel-limites" tabindex="-1" type="button">Alcance do exemplo</button></div><div id="panel-trechos" class="result-panel" role="tabpanel" aria-labelledby="tab-trechos">{''.join(cards)}</div><div id="panel-limites" class="result-panel" role="tabpanel" aria-labelledby="tab-limites" hidden><p>São cinco recortes anotados manualmente, alguns encaixados em outros. Eles não representam uma contagem exaustiva de orações.</p><p>O vínculo de “convidando” fica em revisão. Os infinitivos de “parecia pintar”, “parecia hesitar” e “a mergulhar” também exigem critérios próprios, que não estão implementados aqui.</p><p>O exemplo demonstra extração, explicação, seleção e preservação do original. A capacidade de analisar qualquer texto precisa passar pelas etapas P04 a P06.</p><p>A análise do exemplo é uma aplicação proposta, não uma conclusão emitida pelas referências. A bibliografia de apoio registra leituras comparativas e ambiguidades; os livros enviados orientarão a revisão.</p><ul class="source-list">{sources}</ul></div></div></aside></div><p id="demo-status" role="status" class="quiet" style="margin:20px 0 0">Ligue Escrevaral para abrir a demonstração.</p><noscript><p>A demonstração interativa requer JavaScript. O roteiro e os documentos continuam disponíveis.</p></noscript></div><div class="contract"><div><strong>O editor é do autor.</strong><p>Nenhuma análise substitui, corrige, completa ou apaga o texto. Localizar significa selecionar; nunca aplicar uma mudança.</p></div><div><strong>Uma observação precisa de contexto.</strong><p>Cada trecho deve trazer relação, explicação, fonte, alcance e incerteza. Encontrar “que” não comprova uma oração subordinada.</p></div><div><strong>A explicação tem profundidade opcional.</strong><p>Primeiro, uma leitura simples. Depois, conceitos, exemplos e referências para quem quiser aprender mais, em qualquer idade.</p></div><div><strong>O resultado acompanha a versão do texto.</strong><p>Editar, trocar de folha ou desligar cancela a análise anterior. A versão futura não poderá mostrar trechos desatualizados como atuais.</p></div></div></section>
<section class="chapter" id="continuidade"><div class="section-head"><div><span class="eyebrow">04 · memória de trabalho</span><h2>Para a próxima pessoa.<br>Para a próxima IA.</h2></div><p>O conhecimento durável está nos registros do projeto. Receber livros não treina permanentemente um modelo. Toda entrega deve dizer o que leu, implementou, testou e publicou.</p></div><div class="guides"><article class="guide"><h3>Aprender</h3><p>Da edição e da página à regra, às exceções e ao corpus de avaliação.</p>{link('docs/jornada/COMO-ESTUDAR.md')}</article><article class="guide"><h3>Construir</h3><p>Estados da cortina, trechos exatos, relações entre orações e proteção do manuscrito.</p>{link('docs/jornada/CONTRATO-ANALISE.md')}</article><article class="guide"><h3>Dar continuidade</h3><p>Estado real, decisões, evidências, pendências e próxima ação delimitada.</p>{link('AGENTS.md')}<br>{link('docs/jornada/PASSAGEM-DE-TRABALHO.md')}</article></div><div class="next"><h3>Como esta jornada chega a uma entrega completa?</h3><p>Quando o escopo acordado tiver referências verificáveis, motores reais, avaliação independente, explicações acessíveis e qualidade e custo aprovados. Publicar em lotes permite entregar valor antes disso. A manutenção continua depois da primeira versão completa.</p><p style="margin-bottom:0">A conclusão é do escopo prometido — não uma declaração de que toda a língua foi esgotada.</p></div><p style="margin-top:24px">{link('docs/JORNADA-LINGUISTICA.md')} · {link('docs/jornada/estado.json')} · <a href="https://github.com/rfmss/escrevaral/commits/main/jornada/">Histórico da jornada</a></p></section></div></main><footer class="wrap">Atualização: {h(d['updated'])} · Base do produto auditada: <a href="https://github.com/rfmss/escrevaral/commit/{d['baseline']}">{d['baseline'][:7]}</a>.<br>Estado separado: estudado → implementado → testado → integrado → publicado. <a href="../">Voltar ao Escrevaral</a>.</footer><script>{js}</script></body></html>'''
(ROOT/'jornada/index.html').write_text(page)
md=f'''# Jornada linguística do Escrevaral

Página permanente: https://escrevaral.com/jornada/

Atualizado em {d['updated']}. Base do produto auditada: `{d['baseline']}`.

**Propósito:** {d['purpose']}

**Estado:** {d['current']}

Fonte desta página e do mapa: `docs/jornada/estado.json`. Gerar com `python3 ferramentas/gerar-jornada.py`. Não editar as cópias geradas.

## Compromisso de produto

O autor escreve; liga Escrevaral; escolhe uma única lente; recebe trechos exatos e explicados na mesma área. Nenhuma análise altera, corrige, completa ou substitui o manuscrito. O exemplo público é manual e não certifica um detector geral de subordinadas.

## Fila atual

'''+''.join('- '+x+'\n' for x in d['next'])+'\n## Etapas\n\n'
for p in d['phases']:
 md+=f"### {p['id']} — {p['title']}\n\nEstado: **{p['status']}**. Depende de: {', '.join(p['depends']) or 'base existente'}.\n\n{p['goal']}\n\n"+''.join('- '+t+'\n' for t in p['tasks'])+f"\n**Condição de conclusão:** {p['done']}\n\n"+('Evidências: '+', '.join('`'+x+'`' for x in p['evidence'])+'.\n\n' if p['evidence'] else '')
md+='## Cobertura de estudo\n\n'+''.join('### '+a['title']+'\n\n'+a['scope']+'\n\n' for a in d['areas'])
md+='## Experiência e continuidade\n\n- [Como estudar](jornada/COMO-ESTUDAR.md)\n- [Contrato de análise](jornada/CONTRATO-ANALISE.md)\n- [Passagem de trabalho](jornada/PASSAGEM-DE-TRABALHO.md)\n- [Modelo de regra](jornada/regra-modelo.json)\n- [Instruções para futuras IAs](../AGENTS.md)\n\n## Primeiro conjunto de livros\n\nGuia principal: Cunha e Cintra (B09). Dezessete obras catalogadas; leitura parcial, nenhuma leitura integral declarada. Consulte [inventário](jornada/fontes.json), [leitura inicial](jornada/LEITURA-INICIAL.md) e [corpus proposto](jornada/corpus-inicial.json).\n\n## Exemplo de referência\n\n'+d['sample']+'\n\nOs recortes e suas posições estão em `jornada/estado.json`. São leituras manuais para especificar a experiência; os limites, alternativas e relações são parte da demonstração. Não é uma análise exaustiva.\n\n## Referências de apoio ao exemplo\n\n'+''.join('- ['+s['title']+']('+s['url']+')\n' for s in d['sources'])+'\nAs referências apoiam conceitos gerais; a aplicação ao parágrafo é uma leitura proposta, ainda sem revisão linguística independente.\n\n## Encerramento e manutenção\n\nUma entrega termina quando cumpre seu escopo, tem evidências e limitações registradas e sua publicação é verificada. A primeira jornada termina com os módulos prometidos aprovados, uma interface acessível e custo compatível com os limites definidos para a referência tecnológica, sem exigência de homologação de aparelhos. Manutenção, novos casos e novas obras seguem em versões posteriores.\n'
(ROOT/'docs/JORNADA-LINGUISTICA.md').write_text(md)
